gOI(){return"\u0645\u0644\u0635\u0642 \u062d\u0627\u0644\u0629 \u0635\u063a\u064a\u0631 (A6\u060c 4 \u0628\u0648\u0631\u0642\u0629 A4)"},
gOH(){return"\u0639\u0646\u062f \u0627\u0644\u062a\u0634\u063a\u064a\u0644: \u0645\u0644\u0635\u0642 \u0627\u0644\u062d\u0627\u0644\u0629 \u064a\u0635\u064a\u0631 \u0631\u0628\u0639 \u0648\u0631\u0642\u0629 A4 \u0628\u0646\u0641\u0633 \u062d\u062c\u0645 \u0627\u0644\u062e\u0637\u060c \u0641\u0625\u0630\u0627 \u062a\u0637\u0628\u0639 4 \u0628\u0627\u0644\u0648\u0631\u0642\u0629 \u064a\u0637\u0644\u0639 \u0627\u0644\u062e\u0637 \u0628\u062d\u062c\u0645\u0647 \u0627\u0644\u0643\u0627\u0645\u0644 \u0645\u0648 \u0645\u0635\u063a\u0651\u0631. \u064a\u0646\u0627\u0633\u0628 \u0623\u064a\u0636\u0627\u064b \u0637\u0627\u0628\u0639\u0627\u062a \u0627\u0644\u0645\u0644\u0635\u0642\u0627\u062a 4\xd76 \u0625\u0646\u0634."},
gZG(){return"\u062a\u063a\u064a\u064a\u0631 \u0641\u0646\u064a \u0627\u0644\u0633\u0643\u0646\u0631"},
ga8f(){return"\u0627\u0644\u062d\u062f \u0627\u0644\u0623\u0642\u0635\u0649 \u0644\u0644\u0648\u062d\u062f\u0627\u062a \u0644\u0643\u0644 \u062d\u0627\u0644\u0629 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
ga8e(){return"\u064a\u064f\u062d\u062a\u0633\u0628 \u0647\u0630\u0627 \u0627\u0644\u0639\u062f\u062f \u0645\u0646 \u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0641\u0642\u0637 \u0644\u0643\u0644 \u0637\u0644\u0628\u060c \u0645\u062b\u0644\u0627\u064b 5. \u0627\u062a\u0631\u0643\u0647 \u0641\u0627\u0631\u063a\u0627\u064b \u0628\u062f\u0648\u0646 \u062d\u062f."},
