ga19(){return"\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u0642\u06c6\u0646\u0627\u063a"},
ga0o(){return"\u0626\u06d5\u0631\u0634\u06cc\u0641\u06a9\u0631\u062f\u0646"},
ga11(){return"\u0633\u0695\u06cc\u0646\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0645\u06cc\u0634\u06d5\u06cc\u06cc"},
ga22(){return"\u06af\u06d5\u0695\u0627\u0646\u062f\u0646\u06d5\u0648\u06d5"},
ga0s(){return"\u0626\u06d5\u0631\u0634\u06cc\u0641\u06a9\u0631\u0627\u0648"},
ga0r(){return"\u0626\u06d5\u0645 \u0642\u06c6\u0646\u0627\u063a\u06d5 \u0626\u06d5\u0631\u0634\u06cc\u0641 \u0628\u06a9\u0631\u06ce\u062a\u061f"},
a0q(a){return"\xab"+a+"\xbb \u0644\u06d5 \u0647\u06ce\u06b5\u06cc \u0647\u06d5\u0645\u0648\u0648 \u062c\u06c6\u0631\u06d5 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0648 \u0644\u06d5 \u062a\u06d5\u062e\u062a\u06d5\u06a9\u06d5 \u0644\u0627\u062f\u06d5\u0628\u0631\u062f\u0631\u06ce\u062a. \u06a9\u06d5\u06cc\u0633\u06d5 \u06a9\u06c6\u0646\u06d5\u06a9\u0627\u0646 \u0648 \u0645\u06ce\u0698\u0648\u0648 \u0646\u0627\u0648\u06d5\u06a9\u06d5 \u062f\u06d5\u0647\u06ce\u06b5\u0646\u06d5\u0648\u06d5. \u062f\u0648\u0627\u062a\u0631 \u062f\u06d5\u062a\u0648\u0627\u0646\u06cc\u062a \u0628\u06cc\u06af\u06d5\u0695\u06ce\u0646\u06cc\u062a\u06d5\u0648\u06d5."},
