gOt(){return"\u0648\u06ce\u0646\u06d5\u06af\u0631\u062a\u0646 \u0648 \u0628\u0627\u0631\u06a9\u0631\u0646\u0627 \u0648\u06ce\u0646\u06d5\u06cc\u0627\u0646."},
gOw(){return"\u0631\u06ce\u062f\u0627\u0646 \u0628 \u06a4\u06cc\u062f\u06cc\u06c6\u06cc\u0627\u0646"},
gOx(){return"\u0628\u06c6 \u0644\u0642\u06d5\u06a9\u06ce \u0646\u0648\u06cc \u0628 \u0634\u06ce\u0648\u06d5\u06cc\u06d5\u06a9\u06ce \u0628\u0646\u06d5\u0695\u06d5\u062a \u06a4\u06d5\u0645\u0631\u0627\u06cc\u06d5 \u2014 \u06a4\u06cc\u062f\u06cc\u06c6 \u0628\u06d5\u0631\u06cc \u0628\u0627\u0631\u06a9\u0631\u0646\u06ce \u0646\u0627\u0647\u06ce\u062a\u06d5 \u0628\u0686\u0648\u0648\u06a9\u06a9\u0631\u0646\u060c \u0644\u06d5\u0648\u0645\u0627 \u0645\u06d5\u0632\u0646\u062a\u0631\u06cc\u0646 \u0626\u06d5\u06af\u06d5\u0631\u06d5 \u0628\u06c6 \u062a\u0698\u06cc\u0628\u0648\u0648\u0646\u0627 \u0633\u0646\u0648\u0648\u0631\u06ce \u0628\u06d5\u0644\u0627\u0634 \u06cc\u06ce Supabase."},
gOm(){return"\u0631\u06ce\u062f\u0627\u0646 \u0628 \u062a\u06ce\u0628\u06cc\u0646\u06cc\u06ce\u0646 \u062f\u06d5\u0646\u06af\u06cc"},
gOn(){return"\u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646\u0627 \u062a\u06ce\u0628\u06cc\u0646\u06cc\u06ce\u0646 \u062f\u06d5\u0646\u06af\u06cc \u062f \u0646\u0627\u0645\u06d5\u06cc\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u062f\u0627."},
gOq(){return"\u0631\u06ce\u062f\u0627\u0646 \u0628 \u0628\u06d5\u0644\u06af\u06d5\u0646\u0627\u0645\u06d5\u06cc\u0627\u0646"},
gOr(){return"\u067e\u0627\u0634\u06a9\u06c6\u06cc\u06ce\u0646 PDF/\u0633\u06a9\u0627\u0646\u06cc \u2014 \u0631\u06d5\u0686\u06d5\u062a\u06d5\u060c \u0641\u06c6\u0631\u0645\u06ce\u0646 \u0628\u06cc\u0645\u06d5\u06cc\u06ce \u0648 \u06cc\u06ce\u0646 \u0648\u06d5\u06a9\u06cc \u0648\u0627\u0646."},
gQz(){return"\u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u0646\u0627 \u0631\u06ce\u06a9\u062e\u0633\u062a\u0646\u06ce\u0646 \u0644\u0642\u06cc"},
gR2(){return"\u0634\u06ce\u0648\u0627\u0632\u06ce \u0646\u06d5\u062e\u0634\u06ce \u062f\u062f\u0627\u0646\u0627\u0646"},
gR4(){return"\u0698\u0645\u0627\u0631\u06ce\u0646 \u062f\u062f\u0627\u0646\u0627\u0646 \u0686\u0627\u0648\u0627 \u0644 \u0633\u06d5\u0631 \u0646\u06d5\u062e\u0634\u06d5\u060c \u06a9\u0627\u0631\u062a\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u0648 \u062e\u0634\u062a\u06d5\u06cc\u0627\u0646 \u062f\u06cc\u0627\u0631 \u062f\u0628\u0646 \u2014 \u0626\u06d5\u06a4\u06d5 \u062a\u0646\u06ce \u0647\u06d5\u0644\u0628\u0698\u0627\u0631\u062a\u0646\u0627 \u067e\u06cc\u0634\u0627\u0646\u062f\u0627\u0646\u06ce\u06cc\u06d5\u060c \u0686 \u062a\u0634\u062a \u0628 \u0631\u06d5\u0646\u06af\u06d5\u06a9\u06ce \u062f\u06cc \u0646\u0627\u0647\u06ce\u062a\u06d5 \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u0646."},
gR1(){return"\u0698\u0645\u0627\u0631\u06ce\u0646 FDI"},
