gR_(){return"\u0646\u0645\u0648\u0648\u0646\u06d5: 11\u060c 12\u060c 24\u060c 46"},
gR0(){return"\u0646\u0645\u0648\u0648\u0646\u06d5: UR1\u060c UR2\u060c UL4\u060c LR6"},
gPq(){return"\u067e\u06cc\u0634\u0627\u0646\u062f\u0627\u0646\u0627 \u062f\u0648\u06af\u0645\u06d5\u06cc\u0627 \u0686\u0627\u062a\u0627 \u0647\u0627\u0631\u06cc\u06a9\u0627\u0631\u06cc\u06ce"},
gPr(){return"\u0626\u0627\u06cc\u06a9\u06c6\u0646\u0627 \u0686\u0627\u062a\u06ce \u06cc\u0627 \u0644\u06a4\u06c6\u06a9 \u06cc\u0627 \u0628\u06d5\u0631\u0633\u06a4\u0627 \u067e\u0633\u06cc\u0627\u0631\u06ce\u0646 \u062f\u06d5\u0631\u0628\u0627\u0631\u06d5\u06cc \u0626\u06d5\u067e\u06cc \u062f\u062f\u06d5\u062a. \u0626\u06d5\u06af\u06d5\u0631 \u0631\u06ce\u06af\u0631 \u0628\u06cc\u062a \u0628\u06cc\u0645\u0631\u06cc\u0646\u06d5 \u2014 \u0626\u06d5\u06a4\u06d5 \u062a\u0646\u06ce \u0644 \u0633\u06d5\u0631 \u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u062a\u06d5 \u06a9\u0627\u0631 \u062f\u06a9\u06d5\u062a\u060c \u0646\u06d5 \u06cc\u06ce\u0646 \u0647\u06d5\u06a4\u0627\u0644\u06ce\u0646 \u062a\u06d5."},
gEe(){return"\u0631\u06cc\u0632\u0628\u06d5\u0646\u062f\u06cc\u0627 \u0644\u06cc\u0633\u062a\u06ce"},
gQ_(){return"\u0648\u0627\u0646 \u067e\u06d5\u0631\u06ce\u0646 \u062a\u0648 \u067e\u062a\u0631 \u0628\u06a9\u0627\u0631 \u062f\u0626\u06cc\u0646\u06cc \u0628\u062f\u0627\u0646\u06d5 \u0633\u06d5\u0631\u06ce. \u0626\u06d5\u067e \u0644 \u0633\u06d5\u0631 \u06cc\u0627 \u0626\u06ce\u06a9\u06ce \u06a4\u06d5\u062f\u0628\u06cc\u062a. \u062a\u0646\u06ce \u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u062a\u06d5 \u062f\u0647\u06ce\u062a\u06d5 \u06af\u0648\u0647\u06c6\u0695\u06cc\u0646."},
